import Domain
import Foundation
import Logging
import os
import Utilities

/// Crash-isolated MLX summarization via an external MCP subprocess.
///
/// Keeps the model warm in a separate process. If the subprocess crashes,
/// the main app survives and reports the failure gracefully.
public actor MCPSummarizationPlugin: SummarizationEngine {
    private let launchPath: String
    private let fixedArguments: [String]
    private let logger = AppLogger.for(category: "MCPSummarization")
    private var process: Process?
    private var stdinPipe: Pipe?
    private var stdoutPipe: Pipe?
    private var isModelReady = false

    public init(launchPath: String, arguments: [String] = []) {
        self.launchPath = launchPath
        fixedArguments = arguments
    }

    deinit {
        stdinPipe?.fileHandleForWriting.closeFile()
        stdinPipe?.fileHandleForReading.closeFile()
        stdoutPipe?.fileHandleForWriting.closeFile()
        stdoutPipe?.fileHandleForReading.closeFile()
        process?.terminate()
    }

    /// The OS process identifier of the running MCP subprocess, or nil if not loaded.
    /// Exposed for test verification of process lifecycle (kill/ESRCH checks).
    var processIdentifier: Int32? {
        process?.processIdentifier
    }

    public func loadModel(_ config: SummaryConfig) async throws {
        if isModelReady, let p = process, p.isRunning { return }

        let proc = Process()
        proc.executableURL = URL(fileURLWithPath: launchPath)
        proc.arguments = fixedArguments.isEmpty ? [config.modelId.rawValue] : fixedArguments
        let newStdin = Pipe()
        let newStdout = Pipe()
        proc.standardInput = newStdin
        proc.standardOutput = newStdout
        proc.standardError = FileHandle.nullDevice

        do {
            try proc.run()
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Failed to launch MCP subprocess: \(errDesc, privacy: .public)")
            throw SummarizationError.modelNotLoaded(underlying: error)
        }

        // Give subprocess a moment to initialize
        try await Task.sleep(for: .milliseconds(50))

        guard proc.isRunning else {
            throw SummarizationError.modelNotLoaded(underlying: nil)
        }

        stdinPipe = newStdin
        stdoutPipe = newStdout
        process = proc
        isModelReady = true
        logger.info("MCP subprocess launched at PID \(proc.processIdentifier, privacy: .private)")
    }

    /// Terminates the MCP subprocess and resets ready state. Safe to call
    /// when no process is running. Wire to app-lifecycle teardown (#29).
    public func shutdown() {
        stdinPipe?.fileHandleForWriting.closeFile()
        stdinPipe?.fileHandleForReading.closeFile()
        stdoutPipe?.fileHandleForWriting.closeFile()
        stdoutPipe?.fileHandleForReading.closeFile()
        process?.terminate()
        process = nil
        stdinPipe = nil
        stdoutPipe = nil
        isModelReady = false
        logger.info("MCP subprocess shut down")
    }

    // MARK: - MCP Request Types

    private struct MCPRequest: Encodable {
        let jsonrpc = "2.0"
        let id = 1
        let method = "tools/call"
        let params: Params

        struct Params: Encodable {
            let name = "summarize"
            let arguments: Arguments
        }

        struct Arguments: Encodable {
            let transcript: String
            let speakers: [String]
        }
    }

    public func summarize(
        transcript: String, speakers: [String], meetingType _: MeetingType
    ) async throws -> MeetingSummary {
        guard let proc = process, proc.isRunning else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        guard let stdin = stdinPipe,
              let stdout = stdoutPipe
        else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        let request = MCPRequest(params: .init(arguments: .init(transcript: transcript, speakers: speakers)))
        let requestData = try JSONEncoder().encode(request)
        let header = "Content-Length: \(requestData.count)\r\n\r\n"
        guard let headerData = header.data(using: .utf8) else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        // Write on a detached task to avoid blocking the actor executor
        let stdinHandle = stdin.fileHandleForWriting
        await Task.detached {
            stdinHandle.write(headerData)
            stdinHandle.write(requestData)
        }.value

        // Read response with timeout — DispatchQueue bridges the blocking pipe read off the
        // cooperative thread pool. Task.detached is insufficient: it still parks a cooperative
        // thread on the synchronous availableData call and cannot be interrupted by cancellation.
        let stdoutHandle = stdout.fileHandleForReading
        let responseData: Data = try await withThrowingTaskGroup(of: Data.self) { group in
            group.addTask {
                let continuationBox = OSAllocatedUnfairLock<CheckedContinuation<Data, Never>?>(initialState: nil)
                return await withTaskCancellationHandler {
                    await withCheckedContinuation { (cont: CheckedContinuation<Data, Never>) in
                        continuationBox.withLock { $0 = cont }
                        DispatchQueue.global(qos: .userInitiated).async {
                            let data = stdoutHandle.availableData
                            let c = continuationBox.withLock { box -> CheckedContinuation<Data, Never>? in
                                let tmp = box
                                box = nil
                                return tmp
                            }
                            c?.resume(returning: data)
                        }
                    }
                } onCancel: {
                    let c = continuationBox.withLock { box -> CheckedContinuation<Data, Never>? in
                        let tmp = box
                        box = nil
                        return tmp
                    }
                    c?.resume(returning: Data())
                }
            }
            group.addTask {
                try await Task.sleep(for: TimeoutConfig.mcpResponse)
                throw SummarizationError.generationFailed(underlying: nil)
            }
            guard let result = try await group.next() else {
                throw SummarizationError.generationFailed(underlying: nil)
            }
            group.cancelAll()
            return result
        }

        guard !responseData.isEmpty else {
            throw SummarizationError.generationFailed(underlying: nil)
        }

        // Parse MCP response → MeetingSummary
        let json: [String: Any]
        do {
            guard let parsed = try JSONSerialization.jsonObject(with: responseData) as? [String: Any] else {
                let raw = String(data: responseData, encoding: .utf8) ?? "<binary>"
                logger.error("MCP response type mismatch (expected dict) — raw: \(raw, privacy: .private)")
                throw SummarizationError.generationFailed(underlying: nil)
            }
            json = parsed
        } catch {
            let raw = String(data: responseData, encoding: .utf8) ?? "<binary>"
            logger.error("MCP response JSON parse failed: \(String(reflecting: error), privacy: .public) — raw: \(raw, privacy: .private)")
            throw SummarizationError.generationFailed(underlying: error)
        }

        guard let result = json["result"] as? [String: Any],
              let content = result["content"] as? [[String: Any]],
              let text = content.first?["text"] as? String,
              let summaryData = text.data(using: .utf8)
        else {
            let raw = String(data: responseData, encoding: .utf8) ?? "<binary>"
            logger.error("MCP response structure validation failed — raw: \(raw, privacy: .private)")
            throw SummarizationError.generationFailed(underlying: nil)
        }

        do {
            return try JSONDecoder().decode(MeetingSummary.self, from: summaryData)
        } catch {
            let truncated = String(text.prefix(100))
            logger
                .error(
                    // swiftlint:disable:next line_length
                    "MeetingSummary decode failed: \(String(reflecting: error), privacy: .private) — raw (truncated): \(truncated, privacy: .private)"
                )
            throw SummarizationError.generationFailed(underlying: error)
        }
    }

    public func isReady() async -> Bool {
        guard isModelReady, let p = process else { return false }
        return p.isRunning
    }

    public func generate(prompt: String) async throws -> String {
        throw SummarizationError.generationFailed(underlying: nil)
    }
}

import Foundation

// MARK: - DiagnosticEntry

/// A single diagnostic event. Contains no PII — only technical metadata.
public struct DiagnosticEntry: Codable, Sendable {
    public let eventType: String
    public let modelId: String
    public let errorCode: String?
    public let durationSeconds: Double
    public let appVersion: String
    public let osVersion: String

    public init(
        eventType: String,
        modelId: String,
        errorCode: String?,
        durationSeconds: Double,
        appVersion: String,
        osVersion: String
    ) {
        self.eventType = eventType
        self.modelId = modelId
        self.errorCode = errorCode
        self.durationSeconds = durationSeconds
        self.appVersion = appVersion
        self.osVersion = osVersion
    }
}

// MARK: - DiagnosticsLogger

/// Opt-in local diagnostics log. Disabled by default.
///
/// When `isEnabled` is true, `log(entry:)` appends a newline-delimited JSON
/// line to `logFileURL`. The file is capped at 5 MB — oldest lines are rotated
/// out when the cap is exceeded.
public final class DiagnosticsLogger {

    // MARK: Public API

    /// Whether local diagnostics logging is active. Defaults to `false` (opt-in).
    public var isEnabled: Bool = false

    /// The URL of the log file. Exposed so the UI can implement "View diagnostics".
    public let logFileURL: URL

    /// Placeholder for future crash-report submission. Always `false` in this release.
    public let submitReportEnabled: Bool = false

    // MARK: Private

    private let encoder = JSONEncoder()
    private static let maxFileSize = 5 * 1024 * 1024  // 5 MB

    // MARK: Init

    public init(logFileURL: URL, isEnabled: Bool = false) {
        self.logFileURL = logFileURL
        self.isEnabled = isEnabled
    }

    // MARK: Logging

    /// Appends a JSON-encoded diagnostic entry to the log file.
    /// No-op when `isEnabled` is `false`.
    public func log(entry: DiagnosticEntry) async throws {
        guard isEnabled else { return }

        let data = try encoder.encode(entry)
        var line = data
        line.append(0x0A)  // newline

        let path = logFileURL.path

        if !FileManager.default.fileExists(atPath: path) {
            FileManager.default.createFile(atPath: path, contents: nil)
        }

        let handle = try FileHandle(forWritingTo: logFileURL)
        defer { try? handle.close() }

        try handle.seekToEnd()
        try handle.write(contentsOf: line)

        // Rotate if file exceeds 5 MB
        let attrs = try FileManager.default.attributesOfItem(atPath: path)
        let fileSize = attrs[.size] as? Int ?? 0
        if fileSize > Self.maxFileSize {
            try rotate()
        }
    }

    // MARK: Private

    /// Removes the oldest half of lines so the file stays under the 5 MB cap.
    private func rotate() throws {
        let contents = try String(contentsOf: logFileURL, encoding: .utf8)
        let lines = contents.components(separatedBy: "\n").filter { !$0.isEmpty }
        let keep = lines.dropFirst(lines.count / 2)
        let trimmed = keep.joined(separator: "\n") + "\n"
        try trimmed.write(to: logFileURL, atomically: true, encoding: .utf8)
    }
}

