import Domain
import Foundation
import Logging
import os
import Utilities

/// Persists speaker profiles as a JSON array on disk.
public actor JSONSpeakerProfileStore: SpeakerProfileStore {
    private let fileURL: URL
    private var cache: [SpeakerProfile]?
    private let logger = AppLogger.for(category: "SpeakerStore")

    public init(directory: URL? = nil) {
        let dir = directory ?? FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask).first
            .map { $0.appendingPathComponent(AppConstants.Paths.appDirectoryName, isDirectory: true) }
            ?? URL(fileURLWithPath: NSTemporaryDirectory()).appendingPathComponent(AppConstants.Paths.appDirectoryName, isDirectory: true)
        fileURL = dir.appendingPathComponent(AppConstants.Paths.speakerProfilesFileName)
    }

    public func save(_ profile: SpeakerProfile) async throws {
        var profiles = try await load()
        profiles.append(profile)
        try await persist(profiles)
    }

    public func allProfiles() async throws -> [SpeakerProfile] {
        try await load()
    }

    public func delete(id: SpeakerID) async throws {
        var profiles = try await load()
        profiles.removeAll { $0.id == id }
        try await persist(profiles)
    }

    public func update(_ profile: SpeakerProfile) async throws {
        var profiles = try await load()
        guard let idx = profiles.firstIndex(where: { $0.id == profile.id }) else {
            throw StorageError.readFailed(underlying: nil)
        }
        profiles[idx] = profile
        try await persist(profiles)
    }

    public func updateProfile(id: SpeakerID, transform: @Sendable (SpeakerProfile) -> SpeakerProfile) async throws {
        var profiles = try await load()
        guard let idx = profiles.firstIndex(where: { $0.id == id }) else {
            throw SpeakerError.profileNotFound
        }
        profiles[idx] = transform(profiles[idx])
        try await persist(profiles)
    }

    private func load() async throws -> [SpeakerProfile] {
        if let cache { return cache }
        guard FileManager.default.fileExists(atPath: fileURL.path) else {
            cache = []
            return []
        }
        do {
            try Task.checkCancellation()
            let url = fileURL
            let continuationBox = OSAllocatedUnfairLock<CheckedContinuation<Data, any Error>?>(initialState: nil)
            let data = try await withTaskCancellationHandler {
                try await withCheckedThrowingContinuation { continuation in
                    continuationBox.withLock { $0 = continuation }
                    DispatchQueue.global(qos: .utility).async {
                        let result = Result { try Data(contentsOf: url) }
                        let c = continuationBox.withLock { box -> CheckedContinuation<Data, any Error>? in
                            let tmp = box
                            box = nil
                            return tmp
                        }
                        c?.resume(with: result)
                    }
                }
            } onCancel: {
                let c = continuationBox.withLock { box -> CheckedContinuation<Data, any Error>? in
                    let tmp = box
                    box = nil
                    return tmp
                }
                c?.resume(throwing: CancellationError())
            }
            let profiles = try JSONDecoder().decode([SpeakerProfile].self, from: data)
            cache = profiles
            return profiles
        } catch {
            let errDesc = String(reflecting: error)
            logger.error("Failed to load speaker profiles: \(errDesc, privacy: .public)")
            throw StorageError.readFailed(underlying: error)
        }
    }

    private func persist(_ profiles: [SpeakerProfile]) async throws {
        let dir = fileURL.deletingLastPathComponent()
        do {
            try Task.checkCancellation()
            try Directories.ensureDirectory(at: dir)
            let data = try JSONEncoder().encode(profiles)
            let url = fileURL
            let continuationBox = OSAllocatedUnfairLock<CheckedContinuation<Void, any Error>?>(initialState: nil)
            try await withTaskCancellationHandler {
                try await withCheckedThrowingContinuation { continuation in
                    continuationBox.withLock { $0 = continuation }
                    DispatchQueue.global(qos: .utility).async {
                        let result = Result { try data.write(to: url, options: .atomic) }
                        let c = continuationBox.withLock { box -> CheckedContinuation<Void, any Error>? in
                            let tmp = box
                            box = nil
                            return tmp
                        }
                        c?.resume(with: result)
                    }
                }
            } onCancel: {
                let c = continuationBox.withLock { box -> CheckedContinuation<Void, any Error>? in
                    let tmp = box
                    box = nil
                    return tmp
                }
                c?.resume(throwing: CancellationError())
            }
            cache = profiles
        } catch {
            throw StorageError.writeFailed(underlying: error)
        }
    }
}

