import Foundation

// MARK: - NullAudioPlaybackDriver
//
// A no-op AudioPlaybackDriver for use at the composition root before a real
// AVPlayerDriver (Infrastructure) is wired in, and in tests that don't need
// actual playback. All operations are safe no-ops; duration stays 0 so
// AudioPlayerBar renders nothing (correct: nothing is loaded).
//
// @MainActor isolation: all mutable state is on the main actor.
// teardown() is nonisolated with no state access — safe because there is
// nothing to tear down.

@MainActor
public final class NullAudioPlaybackDriver: AudioPlaybackDriver {
    public var duration: TimeInterval = 0
    public var isPlaying: Bool = false

    public init() {}

    public func load(url _: URL) throws {}
    public func play() {}
    public func pause() {}
    public func seek(to _: TimeInterval) {}
    public func setPeriodicTimeHandler(_ handler: ((TimeInterval) -> Void)?) {}

    /// No state to tear down — safe to call from any context.
    public nonisolated func teardown() {}
}

