public actor RepairTranscriptUseCase {
    private let repairService: any TranscriptRepairService
    private let logger = AppLogger.for(category: "RepairTranscript")

    public init(repairService: any TranscriptRepairService) {
        self.repairService = repairService
    }

    public func execute(transcript: String) async throws -> String {
        logger.info("Starting transcript repair (length: \(transcript.count, privacy: .public) chars)")
        let repaired = try await repairService.repair(transcript: transcript)
        logger.info("Transcript repair completed (repaired length: \(repaired.count, privacy: .public) chars)")
        return repaired
    }
}

