import Domain
import Foundation
import OSLog

public actor ProTranscriptRepairService: TranscriptRepairService {
    private let engine: any SummarizationEngine
    private let logger = Logger(subsystem: "app.the-record", category: "ProTranscriptRepairService")

    public init(engine: any SummarizationEngine) {
        self.engine = engine
    }

    public func repair(transcript: String) async throws -> String {
        logger.info("Executing transcript repair via injected SummarizationEngine")

        let prompt = TranscriptRepairEngine.buildRepairPrompt(transcript: transcript)
        let config = SummaryConfig.default // Can be overridden if needed

        if !(await engine.isReady()) {
            try await engine.loadModel(config)
        }

        return try await engine.generate(prompt: prompt)
    }
}

