import Domain
import DuckDB
import Foundation
import Logging
import Utilities

public actor DuckDBReaderActor: DiarizationReadRepository, NotesReadRepository, RecordingReadRepository, SummaryReadRepository, TranscriptReadRepository {
    private let storageQueue = DispatchSerialQueue(label: "app.the-record.duckdb", qos: .utility)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        storageQueue.asUnownedSerialExecutor()
    }

    public let database: Database
    // internal (not private): DuckDBReaderActorAdmin.swift accesses these via a cross-file
    // extension in the same module. Swift private is file-scoped; actor isolation is the
    // actual safety boundary here.
    let connection: Connection
    let logger = AppLogger.for(category: "DuckDBStorage")

    public init(databasePath: URL?) throws {
        do {
            let store: Database.Store = if let path = databasePath {
                .file(at: path)
            } else {
                .inMemory
            }
            database = try DuckDBInit.openDatabase(store: store)
            connection = try database.connect()
            try Self.setupSchema(connection: connection)
        } catch {
            print("DUCKDB INIT ERROR: \(error)")
            throw StorageError.readFailed(underlying: error)
        }
    }

    private static func setupSchema(connection: Connection) throws {
        // Required DDL statements — any failure is fatal.
        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordings, label: "createRecordings")
        try executeRequired(connection: connection, sql: DuckDBSQL.createSegments, label: "createSegments")
        try executeRequired(connection: connection, sql: DuckDBSQL.createCommitmentsTable, label: "createCommitmentsTable")
        try executeRequired(connection: connection, sql: DuckDBSQL.createMeetingNotes, label: "createMeetingNotes")
        try executeRequired(connection: connection, sql: DuckDBSQL.createSummaries, label: "createSummaries")
        try executeRequired(connection: connection, sql: DuckDBSQL.createRecordingsIndex, label: "createRecordingsIndex")

        // Additive migrations — tolerate "already exists" / "duplicate" / "reason: nil" errors.
        // Migration for existing databases: add is_pending if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addIsPendingColumn, label: "addIsPendingColumn")
        // Migration for Epic 21: add word_timings VARCHAR column to diarized_segments if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addWordTimingsColumn, label: "addWordTimingsColumn")
        // Migration for epic-28 / task-003: add cleaned_mic_audio_url column if not present.
        try executeMigration(connection: connection, sql: DuckDBSQL.addCleanedMicAudioUrlColumn, label: "addCleanedMicAudioUrlColumn")

        try executeRequired(connection: connection, sql: DuckDBSQL.createInferenceTelemetry, label: "createInferenceTelemetry")

        // Bump schema version to reflect the legacy DDL baseline so the migration runner
        // skips steps v0→v4 (already applied above) and only runs pending steps above v4.
        try connection.execute(DuckDBSQL.createSchemaVersion)
        let versionResult = try connection.query(DuckDBSQL.readSchemaVersion)
        let currentVersion: Int32 = versionResult.rowCount > 0
            ? (versionResult[0].cast(to: Int32.self)[0] ?? 0)
            : 0
        if currentVersion < 4 {
            try connection.execute(DuckDBSQL.setSchemaVersion(4))
        }
        do {
            try DuckDBMigrationRunner().migrate(connection: connection)
        } catch {
            // Revert the baseline bump so the next startup can retry rather than boot-loop.
            if currentVersion < 4 {
                try? connection.execute(DuckDBSQL.setSchemaVersion(currentVersion))
            }
            throw error
        }
    }

    /// Executes a DDL statement that must succeed — any error is fatal.
    private static func executeRequired(connection: Connection, sql: String, label: String) throws {
        do {
            try connection.execute(sql)
        } catch {
            print("FAILED \(label): \(error)")
            throw error
        }
    }

    /// Executes an additive migration statement. Errors that indicate the column/table already
    /// exists ("exists", "duplicate", "reason: nil") are silently swallowed; others are rethrown.
    private static func executeMigration(connection: Connection, sql: String, label: String) throws {
        do {
            try connection.execute(sql)
        } catch {
            print("FAILED \(label): \(error)")
            let desc = String(describing: error).lowercased()
            if !desc.contains("exists"), !desc.contains("duplicate"), !desc.contains("reason: nil") {
                throw error
            }
        }
    }

    public init() throws {
        let dbDir = Directories.appSupport
        try Directories.ensureDirectory(at: dbDir)
        let dbURL = dbDir.appendingPathComponent(AppConstants.Paths.databaseFileName)
        try self.init(databasePath: dbURL)
    }

    // MARK: - Prepared Statement Helper

    func prepared(_ sql: String) throws -> PreparedStatement {
        try PreparedStatement(connection: connection, query: sql)

import SwiftUI
import AppKit
import Domain
import Logging
import Business
import AudioInfrastructure
import MLInfrastructure
import Presentation

/// The top-level SwiftUI application entry point for THE RECORD.
@main
public struct TheRecordApp: App {
    /// The application delegate managing the status bar, popover, and composition root.
    @NSApplicationDelegateAdaptor(AppDelegate.self) public var appDelegate

    private let speakerProfileStore = JSONSpeakerProfileStore()

    public init() {}

    public var body: some Scene {
        Window("THE RECORD", id: "main") {
            AppContentView(appDelegate: appDelegate)
                .environment(appDelegate.appState)
        }
        .commands {
            CommandGroup(after: .appInfo) {
                Button("Third-Party Licenses") {
                    if let url = Bundle.main.url(forResource: "ThirdPartyLicenses", withExtension: "txt") {
                        NSWorkspace.shared.open(url)
                    }
                }
            }
            CommandGroup(after: .newItem) {
                Button("New Meeting") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.startRecordingTapped()
                    }
                }
                .keyboardShortcut("n", modifiers: .command)
                .disabled(appDelegate.menuBarVM?.isRecording == true)
                Divider()
                Button("Stop Recording") {
                    Task { @MainActor in
                        await appDelegate.menuBarVM?.stopRecordingTapped()
                    }
                }
                .keyboardShortcut(".", modifiers: .command)
                Divider()
                Button("Re-transcribe from Audio") {
                    Task { @MainActor in
                        if let id = appDelegate.menuBarVM?.cleanupRecordingId {
                            _ = await appDelegate.menuBarVM?.runCleanupPass(recordingId: id)
                        }
                    }
                }
                .keyboardShortcut("r", modifiers: [.command, .shift])
                .disabled(appDelegate.menuBarVM?.cleanupRecordingId == nil || appDelegate.menuBarVM?
                    .isRecording == true)
            }
        }
        Settings {
            if let appState = appDelegate.appState {
                SettingsView(
                    viewModel: SettingsViewModel(
                        appState: appState,
                        profileStore: speakerProfileStore,
                        audioDeviceConfigStore: AudioDeviceConfigStoreImpl(configManager: appDelegate.sharedConfigManager),
                        deviceEnumeration: AudioDeviceEnumerator()
                    ),
                    modelDownloadViewModel: ModelDownloadViewModel(
                        downloadWhisper: { modelId, token in
                            let typedModelId = ModelID(modelId)
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await WhisperKitPlugin().loadModel(typedModelId)
                        },
                        downloadParakeet: { modelId, token in
                            let typedModelId = ModelID(modelId)
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await ParakeetPlugin().loadModel(typedModelId)
                        },
                        downloadMLX: { modelId, token in
                            let config = SummaryConfig(
                                modelId: ModelID(modelId),
                                maxTokens: SummaryConfig.default.maxTokens,
                                temperature: SummaryConfig.default.temperature,
                                enabled: true,
                                meetingType: SummaryConfig.default.meetingType,
                            )
                            if let token { setenv("HF_TOKEN", token, 1) } // swiftlint:disable:this no_setenv
                            defer { if token != nil { unsetenv("HF_TOKEN") } }
                            try await MLXSummarizationPlugin().loadModel(config)
                        },
                        downloadDiarization: {
                            try await FluidDiarizationPlugin().prepare()
                        },
                        tokenStore: HFTokenKeychain(),
                    )
                )
            } else {
                ProgressView()
            }
        }
    }
}

// MARK: - Root Content View

struct AppContentView: View {
    var appDelegate: AppDelegate
    @Environment(AppState.self) private var appState: AppState?

    // AudioPlayerViewModel is owned here and passed into MainWindowView so
    // Presentation never needs to import AVFoundation or Infrastructure directly.
    @State private var audioPlayerVM = AudioPlayerViewModel(driver: AVPlayerDriver())

    var body: some View {
        if let appState,
           let menuBarVM = appDelegate.menuBarVM,
           let libraryVM = appDelegate.libraryVM,
           let searchVM = appDelegate.searchVM,
           let detailVM = appDelegate.detailVM,
           let commitmentsVM = appDelegate.commitmentsVM,
           let waveformVM = menuBarVM.waveformVM {

            switch appState.settings.uiTheme {
            case .broadsheet:
                if let broadsheetAppState = appDelegate.broadsheetAppState {
                    BroadsheetRootView(
                        appState: broadsheetAppState,
                        permissionService: SystemPermissionService(),
                    )
                }
            case .classic:
                MainWindowView(
                    menuBarVM: menuBarVM,
                    libraryVM: libraryVM,
                    searchVM: searchVM,
                    detailVM: detailVM,
                    waveformVM: waveformVM,
                    commitmentsVM: commitmentsVM,
                    audioPlayerVM: audioPlayerVM,
                )
            }
        } else {
            ProgressView("Starting THE RECORD...")
                .frame(maxWidth: .infinity, maxHeight: .infinity)
        }
    }
}

// MARK: - App Delegate

@Observable
@MainActor
public final class AppDelegate: NSObject, NSApplicationDelegate {

    public var statusItem: NSStatusItem?
    public var popover: NSPopover?

    private let assembler = AppAssembler()

    // SSOT Root
    public private(set) var appState: AppState?

    // Legacy Bridge Properties
    public private(set) var uiTheme: UITheme = .default
    public private(set) var defaultEngine: TranscriptionEngineKey = TranscriptionConfig.default.defaultEngine
    public private(set) var archivePassEnabled: Bool = TranscriptionConfig.default.archivePassEnabled
    public private(set) var libraryVM: MeetingLibraryViewModel?
    public private(set) var menuBarVM: MenuBarViewModel?
    public private(set) var searchVM: SearchViewModel?
    public private(set) var detailVM: MeetingDetailViewModel?
    public private(set) var commitmentsVM: CommitmentsViewModel?
    public private(set) var broadsheetAppState: BroadsheetAppState?
    public private(set) var contextSuggestionsVM: ContextSuggestionsViewModel?

    private let logger = AppLogger.for(category: "AppDelegate")
    public let sharedConfigManager = ConfigManager()

    private var themeObserver: NSObjectProtocol?
    private var privacyModeObserver: NSObjectProtocol?
    private var engineObserver: NSObjectProtocol?
    private var archivePassEnabledObserver: NSObjectProtocol?
    private var recordingStartObserver: NSObjectProtocol?
    private var recordingStopObserver: NSObjectProtocol?
    private var windowKeyObserver: NSObjectProtocol?
    private var currentPrivacyMode: PrivacyMode = .default

    public func applicationDidFinishLaunching(_ notification: Notification) {
        let launchConfig = AppConfig.default
        uiTheme = launchConfig.uiTheme
        defaultEngine = launchConfig.transcription.defaultEngine
        archivePassEnabled = launchConfig.transcription.archivePassEnabled
        currentPrivacyMode = launchConfig.privacyMode

        setupConfigObservers()

        Task { @MainActor in
            let assembled = await assembler.assemble(config: launchConfig)
            self.appState = assembled.appState

            // Sync legacy properties
            self.menuBarVM = assembled.menuBarVM
            self.libraryVM = assembled.libraryVM
            self.searchVM = assembled.searchVM
            self.detailVM = assembled.detailVM
            self.commitmentsVM = assembled.commitmentsVM
            self.contextSuggestionsVM = assembled.contextSuggestionsVM

            let appState = assembled.appState
            self.broadsheetAppState = BroadsheetAppState(
                appState: appState,
                menuBarVM: assembled.menuBarVM,
                libraryVM: assembled.libraryVM,
                detailVM: assembled.detailVM,
                commitmentsVM: assembled.commitmentsVM
            )

            self.setupStatusBar(viewModel: assembled.menuBarVM)
        }

        windowKeyObserver = NotificationCenter.default.addObserver(
            forName: NSWindow.didBecomeKeyNotification,
            object: nil,
            queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: self.menuBarVM?.isRecording ?? false)
            }
        }

        logger.info("THE RECORD launched")
    }

    public func applicationWillTerminate(_ notification: Notification) {
        assembler.teardown()
    }

    private func setupConfigObservers() {
        themeObserver = NotificationCenter.default.addObserver(
            forName: .themeChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let theme = note.userInfo?["uiTheme"] as? UITheme else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.uiTheme = theme
                self.appState?.settings.uiTheme = theme
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: current.transcription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: theme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist theme: \(error, privacy: .public)")
                    }
                }
            }
        }

        privacyModeObserver = NotificationCenter.default.addObserver(
            forName: .privacyModeChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let raw = note.userInfo?["privacyMode"] as? String,
                  let mode = PrivacyMode(rawValue: raw)
            else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.currentPrivacyMode = mode
                self.appState?.settings.privacyMode = mode
                self.applyPrivacyMode(mode, isRecording: self.menuBarVM?.isRecording ?? false)
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: current.transcription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: mode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist privacy mode: \(error, privacy: .public)")
                    }
                }
            }
        }

        engineObserver = NotificationCenter.default.addObserver(
            forName: .engineChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let raw = note.userInfo?["defaultEngine"] as? String,
                  let engine = TranscriptionEngineKey(rawValue: raw)
            else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.defaultEngine = engine
                self.appState?.settings.defaultEngine = engine
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let newTranscription = TranscriptionConfig(
                            defaultEngine: engine,
                            fallbackEngine: current.transcription.fallbackEngine,
                            cleanupModelId: current.transcription.cleanupModelId,
                            archivePassEnabled: current.transcription.archivePassEnabled,
                        )
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: newTranscription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist engine selection: \(error, privacy: .public)")
                    }
                }
            }
        }

        archivePassEnabledObserver = NotificationCenter.default.addObserver(
            forName: .archivePassEnabledChanged, object: nil, queue: .main,
        ) { [weak self] note in
            guard let enabled = note.userInfo?["enabled"] as? Bool else { return }
            MainActor.assumeIsolated {
                guard let self else { return }
                self.archivePassEnabled = enabled
                self.appState?.settings.archivePassEnabled = enabled
                Task { [weak self] in
                    guard let self else { return }
                    do {
                        let current = try await self.sharedConfigManager.load()
                        let newTranscription = TranscriptionConfig(
                            defaultEngine: current.transcription.defaultEngine,
                            fallbackEngine: current.transcription.fallbackEngine,
                            cleanupModelId: current.transcription.cleanupModelId,
                            archivePassEnabled: enabled,
                        )
                        let updated = AppConfig(
                            summarization: current.summarization, transcription: newTranscription,
                            storage: current.storage, translation: current.translation,
                            contextCache: current.contextCache, audioCapture: current.audioCapture,
                            uiTheme: current.uiTheme, privacyMode: current.privacyMode,
                            mcpConsentGranted: current.mcpConsentGranted,
                            mcpEndpoints: current.mcpEndpoints,
                            notionEnabled: current.notionEnabled,
                            obsidianVaultPath: current.obsidianVaultPath,
                        )
                        try await self.sharedConfigManager.save(updated)
                    } catch {
                        self.logger.error("Failed to persist archive pass setting: \(error, privacy: .public)")
                    }
                }
            }
        }

        recordingStartObserver = NotificationCenter.default.addObserver(
            forName: .recordingStarted, object: nil, queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: true)
            }
        }

        recordingStopObserver = NotificationCenter.default.addObserver(
            forName: .recordingStopped, object: nil, queue: .main,
        ) { [weak self] _ in
            MainActor.assumeIsolated {
                guard let self else { return }
                self.applyPrivacyMode(self.currentPrivacyMode, isRecording: false)
            }
        }
    }

    private func setupStatusBar(viewModel: MenuBarViewModel) {
        let item = NSStatusBar.system.statusItem(withLength: NSStatusItem.variableLength)
        item.button?.image = NSImage(systemSymbolName: "waveform", accessibilityDescription: "THE RECORD")
        item.button?.action = #selector(togglePopover)
        item.button?.target = self
        statusItem = item

        let pop = NSPopover()
        pop.contentSize = NSSize(width: 320, height: 400)
        pop.behavior = .transient
        pop.contentViewController = NSHostingController(rootView: MenuBarPopover(viewModel: viewModel))
        popover = pop
    }

    private func applyPrivacyMode(_ mode: PrivacyMode, isRecording: Bool) {
        guard let window = NSApp.windows.first else { return }
        let protect: Bool = switch mode {
        case .off: false
        case .always: true
        case .meetings: isRecording
        }
        window.sharingType = protect ? .none : .readOnly
    }

    @objc private func togglePopover() {
        guard let button = statusItem?.button, let pop = popover else { return }
        if pop.isShown {
            pop.performClose(nil)
        } else {
            pop.show(relativeTo: button.bounds, of: button, preferredEdge: .minY)
        }
    }
}

import Foundation

/// Centralized application constants to prevent magic strings and manage default values.
public enum AppConstants {
    /// Bundle identifiers and related constants.
    public enum Bundle {
        /// The main bundle identifier. Falls back to a default if unavailable.
        public static var identifier: String {
            Foundation.Bundle.main.bundleIdentifier ?? "app.the-record"
        }
    }

    /// Application directories and path names.
    public enum Paths {
        /// The main application directory name.
        public static let appDirectoryName = "THE RECORD"

        /// The config directory name.
        public static let configDirectoryName = ".therecord"

        /// The config file name.
        public static let configFileName = "config.json"

        /// The recordings directory name.
        public static let recordingsDirectoryName = "recordings"

        /// The DuckDB database file name.
        public static let databaseFileName = "therecord.duckdb"

        /// The DuckDB commitments database file name.
        public static let commitmentsDatabaseFileName = "commitments.duckdb"

        /// The speaker profiles JSON file name.
        public static let speakerProfilesFileName = "speaker-profiles.json"

        /// The local command server socket file name.
        public static let commandServerSocketFileName = "therecord.sock"

        /// The local command server HMAC secret file name.
        public static let commandServerSecretFileName = "therecord-hmac.secret"

        /// HuggingFace Hub cache path relative to application support or home.
        public static let huggingFaceHubPath = "huggingface/hub"

        /// FluidAudio diarization model path.
        public static let fluidAudioDiarizationPath = "FluidAudio/Models/speaker-diarization"

        /// FluidAudio Parakeet model path.
        public static let fluidAudioParakeetPath = "FluidAudio/Models/parakeet-tdt-0.6b-v3"

        /// HuggingFace cache base path relative to home.
        public static let huggingFaceCacheBasePath = ".cache/huggingface/hub"

        /// WhisperKit CoreML snapshots path.
        public static let whisperKitSnapshotsPath = ".cache/huggingface/hub/models--argmaxinc--whisperkit-coreml/snapshots"

        /// Validates and sanitizes a filename or path component to prevent path traversal.
        /// - Parameter component: The path component to sanitize.
        /// - Returns: A sanitized path component. Throws if invalid.
        public static func sanitizePathComponent(_ component: String) throws -> String {
            let sanitized = component.trimmingCharacters(in: .whitespacesAndNewlines)
            if sanitized.isEmpty || sanitized == "." || sanitized == ".." || sanitized.contains("/") || sanitized.contains("\\") {
                throw CocoaError(.fileReadInvalidFileName)
            }
            return sanitized
        }
    }
}

import AppKit
import Foundation
import Logging
import Domain
import AudioInfrastructure
import MLInfrastructure
import Business
import Presentation
import RecordPro

/// Single composition root for THE RECORD.
///
/// Owns all long-lived infrastructure objects and constructs the full
/// dependency graph when `assemble(config:)` is called.
@MainActor
final class AppAssembler {

    struct Assembled {
        let appState: AppState
        let menuBarVM: MenuBarViewModel
        let libraryVM: MeetingLibraryViewModel
        let searchVM: SearchViewModel
        let detailVM: MeetingDetailViewModel
        let commitmentsVM: CommitmentsViewModel
        let contextSuggestionsVM: ContextSuggestionsViewModel
        let migrationTask: Task<Void, Never>
        let repairUseCase: RepairTranscriptUseCase
    }

    // Long-lived infrastructure — must outlive all VMs.
    var reader: DuckDBReaderActor?
    var writer: DuckDBWriterActor?
    var commandServer: DuckDBCommandServer? // periphery:ignore — retained to keep server alive
    var trackCommitmentsUseCase: TrackCommitmentsUseCase?
    var transcriptionBuilt: TranscriptionSubAssembler.Built?

    let logger = AppLogger.for(category: "AppAssembler")

    // Retained so assemble() can be called again without leaking the previous loop.
    var searchSyncTask: Task<Void, Never>?
    var taskBag = TaskBag()

    /// Stops long-lived infrastructure that requires explicit teardown.
    /// Call from `applicationWillTerminate` (#44).
    func teardown() {
        transcriptionBuilt?.prewarmTask.cancel()
        searchSyncTask?.cancel()
        if let server = commandServer {
            Task { await server.stop() }
        }
    }

    // sequential setup — extraction would harm readability
    // swiftlint:disable:next function_body_length
    func assemble(config: AppConfig, enableCoreAudioListeners: Bool = true) async -> Assembled {
        taskBag = TaskBag()
        let st = await buildStorage()
        // Resolve the commitment use case once — both engine and VM share the same instance.
        let sharedTrackUseCase = trackCommitmentsUseCase ?? TrackCommitmentsUseCase(store: InMemoryCommitmentStore())

        let alignUseCase = AlignTranscriptUseCase(
            sampleLoader: AudioFileLoader(),
            reader: st.reader,
            writer: st.writer
        )
        let (_, engine, suggestionsVM, queryContext) = buildEngine(
            config: config,
            fallbackTrack: sharedTrackUseCase,
            alignment: alignUseCase
        )
        let (libVM, migrationTask) = buildLibraryVM(reader: st.reader, writer: st.writer)
        let (menuBarVM, pipelineCoordinator) = buildMenuBarVM(
            reader: st.reader, writer: st.writer, engine: engine, suggestionsVM: suggestionsVM,
            migrationTask: migrationTask, config: config, queryContext: queryContext,
            enableCoreAudioListeners: enableCoreAudioListeners
        )

        // Initialize the Single Source of Truth
        let appState = AppState(
            recording: menuBarVM.recordingStateVM,
            library: libVM,
            initialConfig: config
        )

        // Late-bind AppState to MenuBarVM
        menuBarVM.bindAppState(appState)

        // Wire PipelineCoordinator to AppState.pipeline
        await pipelineCoordinator.setOnStateChange { [weak appState] cleanup, pipeline in
            guard let appState else { return }
            Task { @MainActor in
                appState.pipeline.cleanupState = cleanup
                appState.pipeline.pipelineState = pipeline
            }
        }

        // Recovery fires AFTER menuBarVM is wired
        taskBag.add(Task {
            do {
                let ids = try await RecoverPendingSessionsUseCase(storage: st.reader)()
                for id in ids {
                    await menuBarVM.recoverPendingSession(id)
                }
            } catch {
                let errDesc = String(reflecting: error)
                logger.error("Crash recovery check failed: \(errDesc, privacy: .public)")
            }
        })

        let commitmentsVM = CommitmentsViewModel(useCase: sharedTrackUseCase)

        let repairEngine = transcriptionBuilt?.summarizationEngine ?? MLXSummarizationPlugin()
        let repairUseCase = RepairTranscriptUseCase(
            repairService: ProTranscriptRepairService(engine: repairEngine)
        )

        let detailVM = MeetingDetailViewModel(
            reader: st.reader, writer: st.writer, repairUseCase: repairUseCase
        )

        // Bind DetailVM to AppState for unified selection auto-loading
        appState.bind(detailVM: detailVM)

        let searchVM = SearchViewModel(
            searchUseCase: SearchRecordingsUseCase(storage: st.reader),
            libraryViewModel: libVM
        )

        // Keep searchVM.meetings in sync with libraryVM whenever it reloads (#85).
        searchSyncTask?.cancel()
        searchSyncTask = Task { @MainActor [weak libVM, weak searchVM] in
            while !Task.isCancelled {
                guard let libVM, let searchVM else { return }
                let slot = OSAllocatedUnfairLock(
                    initialState: CheckedContinuation<Void, Never>?.none,
                )
                await withTaskCancellationHandler {
                    await withCheckedContinuation { (continuation: CheckedContinuation<Void, Never>) in
                        slot.withLock { $0 = continuation }
                        withObservationTracking {
                            searchVM.meetings = libVM.meetings
                        } onChange: {
                            slot.withLock { c in c?.resume()
                                c = nil
                            }
                        }
                    }
                } onCancel: {
                    slot.withLock { c in c?.resume()
                        c = nil
                    }
                }
            }
        }

        return Assembled(
            appState: appState,
            menuBarVM: menuBarVM,
            libraryVM: libVM,
            searchVM: searchVM,
            detailVM: detailVM,
            commitmentsVM: commitmentsVM,
            contextSuggestionsVM: suggestionsVM,
            migrationTask: migrationTask,
            repairUseCase: repairUseCase
        )
    }

}

import Business
import Domain
import Foundation
import Logging
import Observation

@Observable
@MainActor
public final class MeetingDetailViewModel {
    public var selectedMeeting: RecordingMetadata?

    /// The audio file URL for the currently selected meeting.
    /// Used by ``TranscriptTabView`` to load audio into ``AudioPlayerViewModel``.
    public var audioURL: URL? { selectedMeeting?.audioURL }

    public var transcript: String?
    public var segments: [DiarizedSegment] = []

    // #174: summary uses didSet to rebuild summaryMarkdownText once on change,
    // so SummaryTabView reads a pre-built String rather than calling .map/.joined
    // on every body evaluation.
    public var summary: MeetingSummary? {
        didSet { summaryMarkdownText = Self.buildSummaryMarkdown(summary) }
    }

    /// Pre-built markdown string for SummaryTabView. Updated whenever `summary`
    /// changes via `didSet` — never recomputed during SwiftUI body evaluation.
    public private(set) var summaryMarkdownText = ""

    public var notes = ""
    public private(set) var notesError: (any Error)?
    public private(set) var saveError: (any Error)?

    private let reader: any MeetingDetailReadRepository
    private let writer: any MeetingDetailWriteRepository
    private let repairUseCase: RepairTranscriptUseCase?
    private let logger = AppLogger.for(category: "MeetingDetail")
    private var loadTask: Task<Void, any Error>?
    private var saveDebounceTask: Task<Void, Never>?

    public init(
        reader: any MeetingDetailReadRepository,
        writer: any MeetingDetailWriteRepository,
        repairUseCase: RepairTranscriptUseCase? = nil
    ) {
        self.reader = reader
        self.writer = writer
        self.repairUseCase = repairUseCase
    }

    // MARK: - Summary Markdown (#174)

    /// Builds the markdown representation of a `MeetingSummary` without accessing
    /// any @Observable stored properties — safe to call from `didSet`.
    static func buildSummaryMarkdown(_ summary: MeetingSummary?) -> String {
        guard let s = summary else { return "" }
        var md = s.summary
        if !s.topics.isEmpty {
            md += "\n\n## Topics\n" + s.topics.map { "- \($0)" }.joined(separator: "\n")
        }
        if !s.decisions.isEmpty {
            md += "\n\n## Decisions\n" + s.decisions.map { "- \($0)" }.joined(separator: "\n")
        }
        if !s.actionItems.isEmpty {
            md += "\n\n## Action Items\n" + s.actionItems.map { item in
                var line = "- \(item.description)"
                if let who = item.assignee { line += " (\(who))" }
                if let due = item.dueDate {
                    line += " — due \(due.formatted(date: .abbreviated, time: .omitted))"
                }
                return line
            }.joined(separator: "\n")
        }
        if !s.openQuestions.isEmpty {
            md += "\n\n## Open Questions\n" + s.openQuestions.map { "- \($0)" }.joined(separator: "\n")
        }
        return md
    }

    // MARK: - Detail Loading

    public func loadDetail(for meeting: RecordingMetadata) async throws {
        saveDebounceTask?.cancel()
        saveDebounceTask = nil
        loadTask?.cancel()
        selectedMeeting = meeting
        // Don't nil out summary/transcript immediately — keep the previous meeting's
        // content visible until the new one loads to avoid a blank flash.
        let requestedId = meeting.id

        let task = Task { [weak self] in
            guard let self else { return }
            let stored = try await self.reader.getRecording(id: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.transcript = stored.transcript?.fullText

            let loadedSummary = try await self.reader.getSummary(for: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.summary = loadedSummary

            let loadedSegments = try await self.reader.getSegments(id: meeting.id)
            try Task.checkCancellation()
            guard self.selectedMeeting?.id == requestedId else { return }
            self.segments = loadedSegments

            do {
                let loadedNotes = try await self.reader.getNotes(meetingId: requestedId)
                try Task.checkCancellation()
                guard self.selectedMeeting?.id == requestedId else { return }
                self.notes = loadedNotes
            } catch {
                self.logger
                    .error(
                        // swiftlint:disable:next line_length
                        "getNotes failed for \(requestedId, privacy: .public): \(String(describing: error), privacy: .private)"
                    )
                self.notesError = error
            }
        }
        loadTask = task
        try await task.value
    }

    public func saveNotes(_ text: String) async {
        guard let id = selectedMeeting?.id else { return }
        await saveNotes(text, forMeetingId: id)
    }

    /// Saves notes for an explicit meeting ID. Used by the debounce path to avoid
    /// resolving `selectedMeeting` at execution time (which may have changed).
    public func saveNotes(_ text: String, forMeetingId meetingId: RecordingID) async {
        saveError = nil
        do {
            try await writer.saveNotes(meetingId: meetingId, text: text)
        } catch {
            logger
                .error(
                    // swiftlint:disable:next line_length
                    "saveNotes failed for \(meetingId, privacy: .public): \(String(describing: error), privacy: .private)"
                )
            saveError = error
        }
    }

    /// Loads the diarized segments for the currently selected meeting.
    public func loadSegmentsForCurrentMeeting() async throws -> [DiarizedSegment] {
        guard let id = selectedMeeting?.id else { return [] }
        return try await reader.getSegments(id: id)
    }

    /// Persists a summary for the currently selected meeting and updates the local state.
    public func applySummary(_ summary: MeetingSummary) async throws {
        guard let id = selectedMeeting?.id else { return }
        try await writer.saveSummary(for: id, summary: summary)
        self.summary = summary
    }

    /// Debounced entry point for keystroke-driven saves. Cancels any pending save
    /// and schedules a new one after 500 ms so rapid edits coalesce into one write.
    /// The meeting ID is captured at schedule time — not at execution time — to
    /// prevent cross-meeting note corruption when the user switches meetings within
    /// the debounce window.
    public func debouncedSaveNotes(_ text: String) {
        let meetingId = selectedMeeting?.id // capture NOW, before any await
        saveDebounceTask?.cancel()
        saveDebounceTask = Task { [weak self] in
            do { try await Task.sleep(for: .milliseconds(500)) } catch { return }
            guard !Task.isCancelled, let self, let meetingId else { return }
            await self.saveNotes(text, forMeetingId: meetingId)
        }
    }

    public func recordingIDsWithSummaries() async throws -> Set<RecordingID> {
        try await reader.recordingIDsWithSummaries()
    }
}

