// NOT DEAD CODE — pre-built DuckDB-backed cache for CachingContextProvider. Ships with MCP caching.

import Accelerate
import Domain
import DuckDB
import Foundation
import Logging
@preconcurrency import NaturalLanguage

public actor DuckDBContextCache {
    private let cacheQueue = DispatchSerialQueue(label: "app.the-record.contextcache", qos: .utility)
    public nonisolated var unownedExecutor: UnownedSerialExecutor {
        cacheQueue.asUnownedSerialExecutor()
    }

    private let database: Database
    private let connection: Connection
    private let logger = AppLogger.for(category: "ContextCache")
    private var nlEmbedding: NLEmbedding?

    public init(databasePath: URL?) throws {
        let store: Database.Store = if let path = databasePath {
            .file(at: path)
        } else {
            .inMemory
        }
        database = try DuckDBInit.openDatabase(store: store)
        connection = try database.connect()
        try setupSchema(connection: connection)
    }

    private nonisolated func setupSchema(connection: Connection) throws {
        try connection.execute(Self.createTable)
    }

    /// Looks up cached results for the given `query` and `providerID`.
    ///
    /// The cache is keyed on `(query_text, provider_id)` together (ISOL-001).
    /// A hit for provider A is never returned for provider B even when the query
    /// text is identical — preventing cross-provider contamination (F6/#195).
    public func get(query: String, providerID: String, ttlSeconds: Int) throws -> [CachedResult]? {
        let stmt = try PreparedStatement(
            connection: connection,
            query: Self.selectCached
        )
        try stmt.bind(query, at: 1)
        try stmt.bind(providerID, at: 2)
        try stmt.bind(Int32(ttlSeconds), at: 3)
        let result = try stmt.execute()
        guard result.rowCount > 0 else { return nil }

        let titles = result[0].cast(to: String.self)
        let bodies = result[1].cast(to: String.self)
        let urls = result[2].cast(to: String.self)
        let providerIDs = result[3].cast(to: String.self)
        let scores = result[4].cast(to: Double.self)

        var results: [CachedResult] = []
        for i in 0 ..< result.rowCount {
            guard let title = titles[i], let body = bodies[i],
                  let pid = providerIDs[i], let score = scores[i] else { continue }
            results.append(CachedResult(
                title: title, body: body,
                sourceURL: urls[i], providerID: pid,
                relevanceScore: score
            ))
        }
        return results
    }

    /// Stores `results` in the cache, keyed on `(query_text, provider_id)`.
    ///
    /// - Parameters:
    ///   - query: The query text to cache results for.
    ///   - results: The results to store. Each result carries its own `providerID`.
    ///   - emptyProviderID: Provider ID to use when `results` is empty (sentinel record).
    ///     Pass the provider's ID so the empty-result record is scoped to that provider.
    public func put(query: String, results: [CachedResult], emptyProviderID: String = "") async throws {
        // Delete only entries for the providers present in the new result set so
        // other providers' entries for the same query_text are not evicted (ISOL-001).
        let providerIDsToEvict: Set<String> = results.isEmpty
            ? (emptyProviderID.isEmpty ? [] : [emptyProviderID])
            : Set(results.map(\.providerID))

        for pid in providerIDsToEvict {
            let delStmt = try PreparedStatement(connection: connection, query: Self.deleteCached)
            try delStmt.bind(query, at: 1)
            try delStmt.bind(pid, at: 2)
            _ = try delStmt.execute()
        }

        let embeddingBlob: Data? = await embeddingVector(for: query).map { vector in
            vector.withUnsafeBufferPointer { Data(buffer: $0) }
        }

        guard !results.isEmpty else {
            // Empty-result sentinel: record that this provider returned nothing so we
            // don't re-query until the TTL expires (ISOL-001 compatible: scoped to provider).
            let emptyStmt = try PreparedStatement(connection: connection, query: Self.insertCached)
            try emptyStmt.bind(query, at: 1)
            try emptyStmt.bind("", at: 2)
            try emptyStmt.bind("", at: 3)
            try emptyStmt.bind(String?.none, at: 4)
            try emptyStmt.bind(emptyProviderID, at: 5)
            try emptyStmt.bind(0.0, at: 6)
            try emptyStmt.bind(embeddingBlob, at: 7)
            _ = try emptyStmt.execute()
            return
        }

        let stmt = try PreparedStatement(connection: connection, query: Self.insertCached)
        for r in results {
            try stmt.bind(query, at: 1)
            try stmt.bind(r.title, at: 2)
            try stmt.bind(r.body, at: 3)
            try stmt.bind(r.sourceURL, at: 4)
            try stmt.bind(r.providerID, at: 5)
            try stmt.bind(r.relevanceScore, at: 6)
            try stmt.bind(embeddingBlob, at: 7)
            _ = try stmt.execute()
        }
    }

    // swiftlint:disable:next cyclomatic_complexity
    public func getSemantic(
        query: String,
        providerID: String,
        matcher: SemanticCacheMatcher,
        threshold: Double,
        ttlSeconds: Int
    ) async throws -> [CachedResult]? {
        let stmt = try PreparedStatement(connection: connection, query: Self.selectDistinctQueriesWithEmbeddings)
        try stmt.bind(providerID, at: 1)
        let result = try stmt.execute()
        guard result.rowCount > 0 else { return nil }

        let queries = result[0].cast(to: String.self)
        let embeddings = result[1].cast(to: Data.self)

        // Compute query embedding once
        guard let queryVector = await embeddingVector(for: query) else {
            // Fall back to text-based matcher when embedding unavailable
            var bestMatch: (query: String, score: Double)?
            for i in 0 ..< result.rowCount {
                guard let cached = queries[i] else { continue }
                let score = matcher.similarity(between: query, and: cached)
                if score >= threshold, bestMatch.map({ score > $0.score }) ?? true {
                    bestMatch = (cached, score)
                }
            }
            guard let match = bestMatch else { return nil }
            return try get(query: match.query, providerID: providerID, ttlSeconds: ttlSeconds)
        }

        // Pre-filter with vDSP cosine similarity (O(N) vector ops, no ML inference).
        // Use a low pre-filter threshold so no true matches are dropped; verify
        // candidates with matcher.similarity() to preserve numerical compatibility
        // with the NLEmbedding distance scale used elsewhere.
        let preFilterThreshold = max(0.0, threshold - 0.3)
        var candidates: [(query: String, score: Double)] = []

        for i in 0 ..< result.rowCount {
            guard let cached = queries[i], let blob = embeddings[i] else { continue }
            let storedVector: [Double] = blob.withUnsafeBytes {
                Array($0.bindMemory(to: Double.self))
            }
            let coarse = cosineSimilarity(queryVector, storedVector)
            if coarse >= preFilterThreshold {
                candidates.append((cached, coarse))
            }
        }

        guard !candidates.isEmpty else { return nil }

        // Verify candidates with the calibrated NLEmbedding matcher.
        var bestMatch: (query: String, score: Double)?
        for candidate in candidates {
            let score = matcher.similarity(between: query, and: candidate.query)
            if score >= threshold, bestMatch == nil || score > bestMatch!.score {
                bestMatch = (candidate.query, score)
            }
        }

        guard let match = bestMatch else { return nil }
        return try get(query: match.query, providerID: providerID, ttlSeconds: ttlSeconds)
    }

    public func pruneIfNeeded(maxEntries: Int) throws {
        let countResult = try connection.query(Self.countAll)
        let count = countResult[0].cast(to: Int64.self)[0] ?? 0
        guard count > Int64(maxEntries) else { return }
        let excess = count - Int64(maxEntries)
        let stmt = try PreparedStatement(
            connection: connection,
            query: Self.pruneOldest
        )
        try stmt.bind(excess, at: 1)
        _ = try stmt.execute()
        logger
            .info(
                // swiftlint:disable:next line_length
                "Pruned \(excess, privacy: .public) stale context cache entries (\(count, privacy: .public) → \(maxEntries, privacy: .public))"
            )
    }

    public func entryCount() throws -> Int {
        let result = try connection.query(Self.countAll)
        return Int(result[0].cast(to: Int64.self)[0] ?? 0)
    }

    // MARK: - SQL

    private static let createTable = """
    CREATE TABLE IF NOT EXISTS context_cache (
        query_text VARCHAR NOT NULL,
        title VARCHAR NOT NULL,
        body VARCHAR NOT NULL,
        source_url VARCHAR,
        provider_id VARCHAR NOT NULL,
        relevance_score DOUBLE NOT NULL DEFAULT 0,
        cached_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        embedding BLOB
    )
    """

    // Cache lookup is keyed on (query_text, provider_id) to prevent cross-provider
    // contamination (ISOL-001 / F6/#195). $1 = query_text, $2 = provider_id, $3 = ttl seconds.
    private static let selectCached = """
    SELECT title, body, source_url, provider_id, relevance_score
    FROM context_cache
    WHERE query_text = $1
    AND provider_id = $2
    AND EPOCH(CURRENT_TIMESTAMP - cached_at) < $3
    ORDER BY relevance_score DESC
    """

    // $1 = provider_id — scoped to prevent cross-provider embedding leakage (ISOL-001).
    private static let selectDistinctQueriesWithEmbeddings =
        "SELECT DISTINCT query_text, embedding FROM context_cache WHERE provider_id = $1"

    // Scoped delete: removes only entries for the given (query_text, provider_id) pair.
    // $1 = query_text, $2 = provider_id.
    private static let deleteCached =
        "DELETE FROM context_cache WHERE query_text = $1 AND provider_id = $2"

    private static let insertCached = """
    INSERT INTO context_cache (query_text, title, body, source_url, provider_id, relevance_score, embedding) \
    VALUES ($1, $2, $3, $4, $5, $6, $7)
    """

    private static let countAll = "SELECT COUNT(*) FROM context_cache"

    private static let pruneOldest =
        "DELETE FROM context_cache WHERE rowid IN (SELECT rowid FROM context_cache ORDER BY cached_at ASC LIMIT $1)"

    // MARK: - Embedding helpers

    private func embeddingVector(for text: String) async -> [Double]? {
        if nlEmbedding == nil {
            nlEmbedding = await Task.detached(priority: .utility) {
                NLEmbedding.sentenceEmbedding(for: .english)
            }.value
        }
        return nlEmbedding?.vector(for: text)
    }

    private func cosineSimilarity(_ a: [Double], _ b: [Double]) -> Double {
        guard a.count == b.count, !a.isEmpty else { return 0 }
        let dot = vDSP.dot(a, b)
        let magA = vDSP.sumOfSquares(a).squareRoot()
        let magB = vDSP.sumOfSquares(b).squareRoot()
        guard magA > 0, magB > 0 else { return 0 }
        return dot / (magA * magB)
    }
}

public struct CachedResult: Sendable {
    public let title: String
    public let body: String
    public let sourceURL: String?
    public let providerID: String
    public let relevanceScore: Double
}
